create table if not exists public.location_bathroom_verifications (id uuid primary key default gen_random_uuid(), location_id uuid not null references public.locations(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, has_public_bathroom boolean not null, verification_method text not null default 'user', latitude double precision, longitude double precision, distance_meters double precision, created_at timestamptz not null default now()); create index if not exists idx_lbv_location on public.location_bathroom_verifications(location_id,created_at desc); create index if not exists idx_lbv_user on public.location_bathroom_verifications(user_id,created_at desc); alter table public.locations add column if not exists bathroom_verification_status text not null default 'unverified'; alter table public.locations add column if not exists bathroom_verified_at timestamptz; alter table public.locations add column if not exists bathroom_verification_count integer not null default 0; alter table public.locations add column if not exists bathroom_positive_count integer not null default 0; alter table public.locations add column if not exists bathroom_negative_count integer not null default 0; create or replace function public.record_bathroom_verification(p_location_id uuid,p_has_public_bathroom boolean,p_lat double precision,p_lng double precision,p_distance_meters double precision) returns jsonb language plpgsql security definer set search_path=public as $$ declare uid uuid:=auth.uid(); pos integer; neg integer; total integer; status text; begin if uid is null then raise exception 'Authentication required'; end if; if p_distance_meters is null or p_distance_meters > 100 then raise exception 'You must be at the location to verify it'; end if; if exists(select 1 from public.profiles pr where pr.id=uid and (pr.is_business_user=true or pr.is_admin=true)) then status:=case when p_has_public_bathroom then 'verified' else 'not_a_bathroom' end; insert into public.location_bathroom_verifications(location_id,user_id,has_public_bathroom,verification_method,latitude,longitude,distance_meters) values(p_location_id,uid,p_has_public_bathroom,'business_owner_or_admin',p_lat,p_lng,p_distance_meters); else if exists(select 1 from public.location_bathroom_verifications v where v.location_id=p_location_id and v.user_id=uid) then raise exception 'You already verified this location'; end if; insert into public.location_bathroom_verifications(location_id,user_id,has_public_bathroom,verification_method,latitude,longitude,distance_meters) values(p_location_id,uid,p_has_public_bathroom,'user',p_lat,p_lng,p_distance_meters); end if; select count(*) filter(where has_public_bathroom),count(*) filter(where not has_public_bathroom),count(*) into pos,neg,total from public.location_bathroom_verifications where location_id=p_location_id; status:=case when exists(select 1 from public.profiles pr where pr.id=uid and (pr.is_business_user=true or pr.is_admin=true)) then status when pos>=3 then 'verified' when neg>=3 and neg>pos then 'not_a_bathroom' else 'pending' end; update public.locations set bathroom_verification_count=total,bathroom_positive_count=pos,bathroom_negative_count=neg,bathroom_verification_status=status,bathroom_verified_at=case when status in ('verified','not_a_bathroom') then now() else bathroom_verified_at end where id=p_location_id; return jsonb_build_object('status',status,'positive',pos,'negative',neg,'total',total); end; $$; grant execute on function public.record_bathroom_verification(uuid,boolean,double precision,double precision,double precision) to authenticated;
